"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[3914],{9589:e=>{e.exports=JSON.parse('{"functions":[{"name":"Shuffle","desc":"Shuffles an array into a random order and returns it.\\n\\n:::caution Shuffles in place\\nThe table is reordered in place and the same table is returned \u2014 the return value\\nis a convenience, not a copy. Pass `table.clone(t)` if the original order matters.\\n:::\\n\\nOnly the array part is touched, since the walk is driven by `#obj`; string keys\\nare left alone.\\n\\n```lua\\nlocal order = Shuffle(table.clone(spawnPoints))\\n```","params":[{"name":"obj","desc":"Array to shuffle","lua_type":"{ [any]: any }"}],"returns":[{"desc":"The same table, reordered","lua_type":"{ [any]: any }"}],"function_type":"static","source":{"line":35,"path":"src/Shared/Class/Shuffle.luau"}}],"properties":[],"types":[],"name":"Shuffle","desc":"Fisher-Yates shuffle over an array.\\n\\nCopyright (c) 2026 firebit. All rights reserved.\\nfirebit/survival-islands - proprietary and confidential.","source":{"line":9,"path":"src/Shared/Class/Shuffle.luau"}}')}}]);